import { afterAll, beforeAll, describe, expect, it } from "vitest";
import { boundary, usageFixture, usageOwner } from "./fixtures/usage-worker";
import { databaseTestsEnabled } from "./helpers/foundation-db";
import { backfillUsageOwner } from "@/lib/usage-backfill";
import { clearCompletedHistory } from "@/lib/history";

describe.runIf(databaseTestsEnabled)("resumable usage backfill", () => {
  let fixture: Awaited<ReturnType<typeof usageFixture>>;
  beforeAll(async () => {
    fixture = await usageFixture();
    await boundary.db.systemControl.update({
      where: { key: "global" },
      data: { sendingEnabled: false },
    });
  });
  afterAll(async () => {
    if (fixture) await fixture.close();
  });
  async function legacy() {
    const f = await usageOwner(boundary.db, { ready: false });
    const input = await f.input();
    const campaign = await boundary.db.campaign.create({
      data: { userId: f.user.id, templateId: f.template.id, status: "SENDING" },
    });
    const cutover = new Date(Date.now());
    const base = { campaignId: campaign.id, contactId: input.recipientIds[0] };
    const succeeded = await boundary.db.send.create({
      data: {
        ...base,
        status: "SENT",
        deliveryState: "DONE",
        sentAt: new Date(+cutover - 1000),
        attemptedAt: new Date(+cutover - 2000),
      },
    });
    await boundary.db.send.create({
      data: {
        ...base,
        status: "REPLIED",
        deliveryState: "DONE",
        sentAt: new Date(+cutover - 3000),
      },
    });
    const queued = await boundary.db.send.create({ data: base });
    const uncertain = await boundary.db.send.create({
      data: {
        ...base,
        status: "FAILED",
        deliveryState: "UNCERTAIN",
        attemptedAt: new Date(+cutover - 86400001),
      },
    });
    await boundary.db.deliveryReceipt.create({
      data: {
        userId: f.user.id,
        recipientEmail: "[REDACTED_EMAIL]",
        createdAt: cutover,
        sentAt: new Date(+cutover - 4000),
      },
    });
    return { ...f, succeeded, queued, uncertain, cutover };
  }
  it("rolls back a full dry run without checkpoints or queue changes", async () => {
    const f = await legacy();
    expect((await backfillUsageOwner(f.user.id, f.cutover)).ready).toBe(true);
    expect(
      await boundary.db.usageReservation.count({
        where: { userId: f.user.id },
      }),
    ).toBe(0);
    expect(
      await boundary.db.usageImportEvidence.count({
        where: { userId: f.user.id },
      }),
    ).toBe(0);
    expect(
      await boundary.db.user.findUnique({ where: { id: f.user.id } }),
    ).toMatchObject({ usageBackfillVersion: 0, usageCutoverAt: null });
    expect(
      await boundary.db.send.findFirst({
        where: { id: f.queued.id, campaign: { userId: f.user.id } },
      }),
    ).toMatchObject({ queueExpiresAt: null });
  });
  it("backfills twice identically, preserves fallback provenance, and never extends original expiry", async () => {
    const f = await legacy();
    await backfillUsageOwner(f.user.id, f.cutover, true);
    const read = async () => ({
      periods: await boundary.db.usagePeriod.findMany({
        where: { userId: f.user.id },
        orderBy: { id: "asc" },
      }),
      evidence: await boundary.db.usageImportEvidence.findMany({
        where: { userId: f.user.id },
        orderBy: { id: "asc" },
      }),
      reservations: await boundary.db.usageReservation.findMany({
        where: { userId: f.user.id },
        orderBy: { id: "asc" },
      }),
    });
    const first = await read();
    await backfillUsageOwner(f.user.id, new Date(+f.cutover + 600000), true);
    expect(await read()).toEqual(first);
    expect(first.evidence.map((e) => e.timestampSource).sort()).toEqual([
      "attemptedAt",
      "sentAt",
      "sentAt",
    ]);
    expect(
      await boundary.db.send.findFirst({
        where: { id: f.queued.id, campaign: { userId: f.user.id } },
      }),
    ).toMatchObject({ queueExpiresAt: new Date(+f.cutover + 86400000) });
    expect(
      first.reservations.find((r) => r.sendId === f.uncertain.id),
    ).toMatchObject({
      chargedAt: f.uncertain.attemptedAt,
      status: "UNCERTAIN",
    });
    await clearCompletedHistory(f.user.id);
    await backfillUsageOwner(f.user.id, f.cutover, true);
    expect((await read()).evidence).toEqual(first.evidence);
  });
  it("commits owner checkpoints independently so an interrupted run can resume", async () => {
    const a = await legacy(),
      b = await legacy();
    await backfillUsageOwner(a.user.id, a.cutover, true);
    // Resume after a hypothetical process exit between owner transactions.
    await backfillUsageOwner(a.user.id, a.cutover, true);
    await backfillUsageOwner(b.user.id, a.cutover, true);
    for (const f of [a, b])
      expect(
        await boundary.db.user.findUnique({ where: { id: f.user.id } }),
      ).toMatchObject({ usageBackfillVersion: 1, usageCutoverAt: a.cutover });
  });
});
